"""Populating Next Right Pointers in Each Node — stitch the level below.

The tree is perfect, so the already-linked current level can be used to connect
the next one without a queue.

Time: O(n)   Space: O(1)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right
            self.next = None


class Solution:
    def connect(self, root):
        leftmost = root
        while leftmost and leftmost.left:
            node = leftmost
            while node:
                node.left.next = node.right
                node.right.next = node.next.left if node.next else None
                node = node.next
            leftmost = leftmost.left
        return root
